CREATE TYPE "CookbookRole" AS ENUM ('OWNER', 'EDITOR', 'COMMENTER', 'READER');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "displayName" TEXT NOT NULL, "dietaryPreferences" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "allergies" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "favoriteCuisines" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "defaultServings" INTEGER NOT NULL DEFAULT 2, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Cookbook" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "description" TEXT, "ownerId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CookbookMember" ("id" TEXT PRIMARY KEY, "cookbookId" TEXT NOT NULL REFERENCES "Cookbook"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "role" "CookbookRole" NOT NULL DEFAULT 'READER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("cookbookId", "userId"));
CREATE TABLE "Recipe" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "description" TEXT, "preparationMinutes" INTEGER NOT NULL, "cookingMinutes" INTEGER NOT NULL, "servings" INTEGER NOT NULL, "imageUrl" TEXT, "sourceUrl" TEXT, "ingredients" JSONB NOT NULL, "steps" JSONB NOT NULL, "tags" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "authorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "cookbookId" TEXT REFERENCES "Cookbook"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Favorite" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "recipeId" TEXT NOT NULL REFERENCES "Recipe"("id") ON DELETE CASCADE, UNIQUE("userId", "recipeId"));
CREATE TABLE "Comment" ("id" TEXT PRIMARY KEY, "content" TEXT NOT NULL, "recipeId" TEXT NOT NULL REFERENCES "Recipe"("id") ON DELETE CASCADE, "authorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Message" ("id" TEXT PRIMARY KEY, "content" TEXT NOT NULL, "cookbookId" TEXT NOT NULL REFERENCES "Cookbook"("id") ON DELETE CASCADE, "authorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MealPlan" ("id" TEXT PRIMARY KEY, "plannedFor" TIMESTAMP(3) NOT NULL, "mealType" TEXT NOT NULL, "servings" INTEGER NOT NULL, "notes" TEXT, "recipeId" TEXT NOT NULL REFERENCES "Recipe"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "cookbookId" TEXT REFERENCES "Cookbook"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
